fn decimal_byte(text: &str) -> Option<u8> {
    let text = text.trim();
    if text.is_empty()
        || !text.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    text.parse().ok()
}
fn main() {
    assert_eq!(decimal_byte("255"), Some(255));
    assert_eq!(decimal_byte("256"), None);
    assert_eq!(decimal_byte("+1"), None);
}

